import React, {useEffect, useState} from 'react'
import {Link} from 'react-router-dom'
import {useAuth} from '../auth'
import Recipe from './Recipe'
import {Button, Form, Modal} from 'react-bootstrap'
import {useForm} from 'react-hook-form'


const LoggedinHome = () => {
    const [recipes, setRecipe] = useState([]);
    const [show, setShow] = useState(false)
    const{register, reset, handleSubmit, setValue, formState:{errors}}= useForm();
    const [selectedRecipeId, setSelectedRecipeId] = useState(null);
    useEffect(
        () => {
            fetch('/recipe/recipes')
                .then(res => res.json())
                .then(data => {
                    setRecipe(data)
                })
                .catch(err => console.log(err))
        }, []
    );

    const getAllRecipes=()=>{
        fetch('/recipe/recipes')
                .then(res => res.json())
                .then(data => {
                    setRecipe(data)
                })
                .catch(err => console.log(err))

    }



    const closeModal = () => {
        setShow(false)
    }
    const showModal = (id) => {
        setShow(true)
        setSelectedRecipeId(id);


       const selectedRecipe = recipes.find(recipe => recipe.id === id);
       if (selectedRecipe){
           setValue('title', selectedRecipe.title);
           setValue('description', selectedRecipe.description);
       }

    };

    let token = localStorage.getItem('REACT_TOKEN_AUTH_KEY')

    const updateRecipe=(data)=>{
        console.log(data)


        const requestOptions={
            method:'PUT',
            headers:{
                'content-type':'application/json',
                'Authorization':`Bearer ${JSON.parse(token)}`
            },
            body:JSON.stringify(data)
        }


        fetch(`/recipe/recipe/${selectedRecipeId}`, requestOptions)
            .then(res=>res.json())
            .then(data=>{console.log(data)
                const reload = window.location.reload()
                reload()
            })
            .catch(err=>console.log(err))

    }

    const deleteRecipe=(id)=>{
        console.log(id)


         const requestOptions={
            method:'DELETE',
            headers:{
                'content-type':'application/json',
                'Authorization':`Bearer ${JSON.parse(token)}`
            }
        }

        fetch(`/recipe/recipe/${id}`, requestOptions)
            .then(res=>res.json())
            .then(data=>{
                console.log(data)

            })
            .catch(err=>console.log(err))
    }




    return (
        <div className={"recipes container"}>
            <Modal
                show={show}
                size={"lg"}
                onHide={closeModal}
            >
                <Modal.Header closeButton>
                    <Modal.Title>
                        Update Recipe
                    </Modal.Title>

                </Modal.Header>
                <Modal.Body>
                    <form>
                        <Form.Group>
                            <Form.Label>Title</Form.Label>
                            <Form.Control type={'Text'}
                                          {...register('title', {required: true, maxLength: 25})}

                            />
                        </Form.Group>
                        {errors.title && <p style={{color: 'red'}}><small>Title is required</small></p>}
                        {errors.title?.type === "maxLength" &&
                        <p style={{color: 'red'}}><small>Title should be less than 25 characters</small></p>}
                        <Form.Group>
                            <Form.Label>Description</Form.Label>
                            <Form.Control as={"textarea"} rows={5}
                                          {...register('description', {required: true, maxLength: 255})}

                            />
                        </Form.Group>
                        {errors.description && <p style={{color: 'red'}}><small>Description is required</small></p>}
                        {errors.description?.type === "maxLength" &&
                        <p style={{color: 'red'}}><small>Description should be less than 255 characters</small></p>}
                        <br></br>
                        <Form.Group>
                            <Button variant={"primary"} onClick={handleSubmit(updateRecipe)}>
                                Save
                            </Button>
                        </Form.Group>
                    </form>
                </Modal.Body>

            </Modal>
            <h1>List of Recipes</h1>
            {
                recipes.map(
                    (recipe, index) => (
                        <Recipe title={recipe.title}
                                key={index}
                                description={recipe.description}
                                onClick={()=>{showModal(recipe.id)}}

                                onDelete={()=>{deleteRecipe(recipe.id)}}
                        />
                    )
                )

            }

        </div>
    )
}

const LoggedOutHome = () => {
    return (
        <div className="home container">
            <h1 className={'heading'}>Welcome to the Recipes</h1>
            <Link to={"/signup"} className={"btn btn-primary btn-lg"}>Get Started</Link>
        </div>
    )
}


const HomePage = () => {
    const [logged] = useAuth()
    return (
        <div>
            {logged ? <LoggedinHome/> : <LoggedOutHome/>}
        </div>

    )
}

export default HomePage
